import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../../data/models/shift_model.dart';
import 'shift_card.dart';
class ShiftWeekView extends StatelessWidget { const ShiftWeekView({required this.weekStart, required this.shifts, required this.onShiftTap, super.key}); final DateTime weekStart; final List<ShiftModel> shifts; final ValueChanged<ShiftModel> onShiftTap; @override Widget build(BuildContext context) { final days = List.generate(7, (i) => weekStart.add(Duration(days: i))); return Row(crossAxisAlignment: CrossAxisAlignment.start, children: days.map((day) { final key = DateFormat('yyyy-MM-dd').format(day); final dayShifts = shifts.where((s) => s.date == key).toList(); return Expanded(child: Column(children: [Container(width: double.infinity, padding: const EdgeInsets.all(8), color: DateUtils.isSameDay(day, DateTime.now()) ? Theme.of(context).colorScheme.primary : Colors.grey.shade200, child: Column(children: [Text(DateFormat('EEE').format(day)), Text(DateFormat('d').format(day), style: const TextStyle(fontWeight: FontWeight.bold))])), ...dayShifts.map((s) => ShiftCard(shift: s, onTap: () => onShiftTap(s)))])); }).toList()); } }
